// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/fraunces";
import "@fontsource/noto-serif-kr";

export const fraunces = { variable: "" };
export const notoSerifKR = { variable: "" };

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { fraunces, notoSerifKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "PAPER FOLD";

/**
 * PAPER FOLD 종이접기 — folding hands, a papercraft atelier. The signature
 * is an origami crane built from folded paper facets (SVG <polygon>s in
 * graded paper tones) with crease lines that draw themselves in
 * (stroke-dashoffset). It sits on warm washi with a faint feTurbulence paper
 * grain. The wordmark is Fraunces, warm orange, with a soft paper drop
 * shadow — design you can almost feel the fold of.
 *
 * `.paper-fold-js` is added on mount so the no-JS markup is the finished
 * page: the crane stands fully drawn, copy is readable, grain is visible.
 */
export default function PaperFoldPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const craneRef = useRef<SVGSVGElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("paper-fold-js");
    const id = requestAnimationFrame(() => root.classList.add("is-mounted"));
    window.parent?.postMessage({ type: "oneshot:ready", slug: "paper-fold" }, "*");
    return () => cancelAnimationFrame(id);
  }, []);

  // svg-line-draw: when the crane scrolls into view, measure each crease path
  // and animate its dashoffset from full-length to 0. NaN-safe lengths are
  // skipped. Reduced motion draws everything instantly.
  useEffect(() => {
    const svg = craneRef.current;
    if (!svg) return;
    const paths = Array.from(svg.querySelectorAll<SVGPathElement>(".fo-crease"));
    const measure = () => {
      for (const p of paths) {
        const len = p.getTotalLength();
        // NaN-safe: skip any path that reports no length.
        if (!Number.isFinite(len) || len <= 0) continue;
        p.style.setProperty("--fo-len", `${len.toFixed(2)}`);
      }
    };
    measure();

    // Reduced motion: the CSS reduced block forces stroke-dashoffset:0, so the
    // creases stand fully drawn with no animation. Nothing else to do.
    if (reduced) return;
    if (!("IntersectionObserver" in window)) {
      svg.classList.add("fo-drawn");
      return;
    }
    const io = new IntersectionObserver(
      (hits) => {
        for (const h of hits) {
          if (h.isIntersecting) {
            svg.classList.add("fo-drawn");
            io.disconnect();
            break;
          }
        }
      },
      { threshold: 0.3 },
    );
    io.observe(svg);
    return () => io.disconnect();
  }, [reduced]);

  return (
    <div
      ref={rootRef}
      className={`${fraunces.variable} ${notoSerifKR.variable} paper-fold-root`}
    >
      <div className="paper-fold-bg" aria-hidden="true" />
      {/* Paper grain — static feTurbulence over everything. */}
      <svg className="paper-fold-grain" aria-hidden="true" focusable="false">
        <filter id="fo-grain">
          <feTurbulence type="fractalNoise" baseFrequency="0.8" numOctaves="2" seed="4" stitchTiles="stitch" />
          <feColorMatrix type="matrix" values="0 0 0 0 0.32  0 0 0 0 0.22  0 0 0 0 0.10  0 0 0 0.06 0" />
        </filter>
        <rect width="100%" height="100%" filter="url(#fo-grain)" />
      </svg>

      <div ref={revealRef} className="paper-fold-doc">
        <header className="paper-fold-hero">
          <p className="paper-fold-kicker">
            <span lang="ko">접는 손</span> · FOLDING HANDS · ATELIER ORI
          </p>
          <h1 className="paper-fold-title" aria-label={TITLE}>
            {TITLE.split("").map((ch, i) => (
              <span
                key={i}
                aria-hidden="true"
                className={`paper-fold-glyph${ch === " " ? " paper-fold-glyph--sp" : ""}`}
                style={{ "--fo-i": i } as CSSProperties}
              >
                {ch}
              </span>
            ))}
          </h1>
          <p className="paper-fold-title__ko" lang="ko">종이접기</p>
          <p className="paper-fold-sub">
            <span lang="ko">한 장의 종이가 새가 되는 시간.</span>{" "}
            The hour a single sheet becomes a bird.
          </p>
        </header>

        <main>
          <section className="paper-fold-stage" data-reveal>
            <svg
              ref={craneRef}
              className="paper-fold-crane"
              viewBox="0 0 600 420"
              role="img"
              aria-label="An origami crane built from folded paper facets"
            >
              <defs>
                <linearGradient id="fo-face-a" x1="0" y1="0" x2="1" y2="1">
                  <stop offset="0" stopColor="#fbf3e2" />
                  <stop offset="1" stopColor="#ecd6ad" />
                </linearGradient>
                <linearGradient id="fo-face-b" x1="0" y1="0" x2="1" y2="1">
                  <stop offset="0" stopColor="#f3e2c0" />
                  <stop offset="1" stopColor="#dcc086" />
                </linearGradient>
                <linearGradient id="fo-face-c" x1="0" y1="0" x2="1" y2="1">
                  <stop offset="0" stopColor="#e9c98f" />
                  <stop offset="1" stopColor="#c79f5e" />
                </linearGradient>
                <radialGradient id="fo-shadow" cx="0.5" cy="0.5" r="0.5">
                  <stop offset="0" stopColor="rgba(120,80,30,0.30)" />
                  <stop offset="1" stopColor="rgba(120,80,30,0)" />
                </radialGradient>
              </defs>

              {/* ground shadow */}
              <ellipse cx="300" cy="362" rx="170" ry="22" fill="url(#fo-shadow)" />

              {/* folded facets — distinct paper tones */}
              <polygon points="300,150 470,250 300,330" fill="url(#fo-face-a)" stroke="#b98a3e" strokeWidth="0.8" />
              <polygon points="300,150 130,250 300,330" fill="url(#fo-face-b)" stroke="#b98a3e" strokeWidth="0.8" />
              <polygon points="300,150 300,330 250,300" fill="url(#fo-face-c)" stroke="#b98a3e" strokeWidth="0.8" />
              <polygon points="300,150 470,250 520,210 360,120" fill="url(#fo-face-b)" stroke="#b98a3e" strokeWidth="0.8" />
              <polygon points="300,150 130,250 80,210 240,120" fill="url(#fo-face-a)" stroke="#b98a3e" strokeWidth="0.8" />
              {/* tail */}
              <polygon points="470,250 300,330 540,330 520,210" fill="url(#fo-face-c)" stroke="#b98a3e" strokeWidth="0.8" />
              {/* head + beak */}
              <polygon points="80,210 240,120 150,150 70,210" fill="url(#fo-face-a)" stroke="#b98a3e" strokeWidth="0.8" />
              <polygon points="80,210 70,210 60,222 78,220" fill="#d4571f" />
              {/* wing lift */}
              <polygon points="300,150 360,120 300,90 240,120" fill="url(#fo-face-b)" stroke="#b98a3e" strokeWidth="0.8" />

              {/* crease lines — drawn in via dashoffset */}
              <path className="fo-crease" d="M300,150 L300,330" />
              <path className="fo-crease" d="M300,150 L470,250" />
              <path className="fo-crease" d="M300,150 L130,250" />
              <path className="fo-crease" d="M300,150 L360,120 L300,90 L240,120 L300,150" />
              <path className="fo-crease" d="M470,250 L540,330" />
              <path className="fo-crease" d="M80,210 L150,150 L240,120" />
            </svg>
          </section>

          <section className="paper-fold-lead" data-reveal>
            <p className="paper-fold-lead__p">
              <span lang="ko">
                접는다는 것은 줄이는 일이 아니다. 한 장의 종이가 수십 번 접히며
                날개를 얻고, 부리를 얻고, 마침내 새가 된다. 우리는 그 접힌 자국
                하나하나를 디자인이라 부른다.
              </span>{" "}
              Folding is not subtracting. A single sheet, folded dozens of
              times, gains wings, gains a beak, and at last becomes a bird. We
              call every one of those creases design.
            </p>
          </section>

          <section className="paper-fold-steps">
            {[
              { ko: "자르기", en: "Cut", n: "01" },
              { ko: "접기", en: "Fold", n: "02" },
              { ko: "펴기", en: "Crisp", n: "03" },
              { ko: "세우기", en: "Stand", n: "04" },
            ].map((c, i) => (
              <article
                key={i}
                className="fo-step"
                data-reveal
                style={{ "--fo-d": i * 90 } as CSSProperties}
              >
                <span className="fo-step__n">{c.n}</span>
                <span className="fo-step__en">{c.en}</span>
                <span className="fo-step__ko" lang="ko">{c.ko}</span>
              </article>
            ))}
          </section>
        </main>

        <footer className="paper-fold-foot">
          <span>PAPER FOLD · 2026</span>
          <span lang="ko">종이접기 — 교토 타카야마</span>
        </footer>
      </div>
    </div>
  );
}

.paper-fold-root {
  --fo-bg: #f6efe2;
  --fo-bg2: #efe5d2;
  --fo-ink: #3a2a18;
  --fo-mute: #8a7457;
  --fo-line: #d8c39a;
  --fo-orange: #d4571f;
  --fo-orange2: #b8430f;
  --fo-paper: #fbf3e2;
  --fo-font-display: "Fraunces", Georgia, serif;
  --fo-font-kr: "Noto Serif KR", serif;
  --fo-ease: cubic-bezier(0.16, 1, 0.3, 1);

  position: relative;
  min-height: 100vh;
  margin: 0;
  background: var(--fo-bg);
  color: var(--fo-ink);
  font-family: var(--fo-font-kr);
  font-weight: 400;
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* Atmospheric depth: warm wash + soft corner shade, like light on paper. */
.paper-fold-bg {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(60% 50% at 20% 0%, rgba(212, 87, 31, 0.07), transparent 70%),
    radial-gradient(60% 60% at 100% 100%, rgba(120, 80, 30, 0.10), transparent 70%),
    linear-gradient(160deg, var(--fo-paper) 0%, var(--fo-bg) 35%, var(--fo-bg2) 100%);
}
/* Static paper grain over everything. */
.paper-fold-grain {
  position: fixed;
  inset: 0;
  z-index: 0;
  width: 100vw;
  height: 100vh;
  pointer-events: none;
  mix-blend-mode: multiply;
  opacity: 0.9;
}

.paper-fold-doc {
  position: relative;
  z-index: 1;
  max-width: 1120px;
  margin: 0 auto;
  padding: clamp(1.4rem, 4vw, 3rem);
}

.paper-fold-root ::selection {
  background: var(--fo-orange);
  color: #fff;
}

/* ---- Hero ---- */
.paper-fold-hero {
  padding: clamp(2.5rem, 8vh, 5rem) 0 clamp(1.5rem, 4vw, 2.5rem);
}
.paper-fold-kicker {
  margin: 0 0 1.2rem;
  font-family: var(--fo-font-display);
  font-size: clamp(0.72rem, 1.1vw, 0.86rem);
  font-weight: 500;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: var(--fo-orange);
}
.paper-fold-kicker span[lang="ko"] { color: var(--fo-mute); margin-right: 0.5rem; letter-spacing: 0.16em; font-family: var(--fo-font-kr); }
.paper-fold-title {
  margin: 0;
  font-family: var(--fo-font-display);
  font-weight: 900;
  font-size: clamp(3rem, 13vw, 10rem);
  line-height: 0.92;
  letter-spacing: -0.025em;
  color: var(--fo-orange);
  /* paper drop shadow: soft, warm, off-axis — like ink lifted off the page. */
  text-shadow:
    1px 1px 0 rgba(255, 255, 255, 0.6),
    2px 6px 0 rgba(184, 67, 15, 0.18),
    0 18px 38px rgba(120, 80, 30, 0.22);
}
.paper-fold-glyph { display: inline-block; }
.paper-fold-glyph--sp { width: 0.28em; }
.paper-fold-title__ko {
  margin: 0.8rem 0 0;
  font-family: var(--fo-font-kr);
  font-weight: 500;
  font-size: clamp(1rem, 2.2vw, 1.5rem);
  letter-spacing: 0.4em;
  color: var(--fo-mute);
}
.paper-fold-sub {
  margin: 1.4rem 0 0;
  max-width: 50ch;
  font-size: clamp(1rem, 1.7vw, 1.25rem);
}
.paper-fold-sub span[lang="ko"] { display: block; color: var(--fo-mute); font-size: 0.84em; margin-bottom: 0.3rem; }

/* ---- Crane stage ---- */
.paper-fold-stage {
  position: relative;
  margin: clamp(1.5rem, 4vw, 2.5rem) 0;
  padding: clamp(1.5rem, 4vw, 3rem) clamp(1rem, 3vw, 2rem);
  background: rgba(251, 243, 226, 0.55);
  border: 1px solid var(--fo-line);
  border-radius: 6px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.8) inset,
    0 24px 50px -34px rgba(120, 80, 30, 0.4);
  text-align: center;
  overflow: hidden;
}
.paper-fold-stage::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(120, 80, 30, 0.06));
  pointer-events: none;
}
.paper-fold-crane {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 560px;
  height: auto;
  display: block;
  margin: 0 auto;
  filter: drop-shadow(0 14px 16px rgba(120, 80, 30, 0.22));
}
/* crease lines — invisible until measured, then drawn when .fo-drawn. */
.fo-crease {
  fill: none;
  stroke: var(--fo-orange2);
  stroke-width: 1.4;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: var(--fo-len, 1);
  stroke-dashoffset: var(--fo-len, 1);
  transition: stroke-dashoffset 1400ms var(--fo-ease);
}
.paper-fold-crane.fo-drawn .fo-crease { stroke-dashoffset: 0; }

/* ---- Lead ---- */
.paper-fold-lead {
  padding: clamp(1.5rem, 4vw, 2.5rem) 0;
  border-top: 1px solid var(--fo-line);
}
.paper-fold-lead__p {
  margin: 0 auto;
  max-width: 60ch;
  font-size: clamp(1.05rem, 2vw, 1.45rem);
  line-height: 1.6;
}
.paper-fold-lead__p span[lang="ko"] {
  display: block;
  color: var(--fo-mute);
  font-size: 0.82em;
  margin-bottom: 0.6em;
}

/* ---- Steps ---- */
.paper-fold-steps {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(0.7rem, 1.4vw, 1.1rem);
  padding-bottom: clamp(2rem, 5vw, 3rem);
}
.fo-step {
  position: relative;
  padding: clamp(1.1rem, 2vw, 1.5rem);
  border-radius: 4px;
  background: var(--fo-paper);
  border: 1px solid var(--fo-line);
  box-shadow: 0 1px 0 rgba(255,255,255,0.7) inset, 0 12px 24px -22px rgba(120,80,30,0.5);
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}
.fo-step__n { font-family: var(--fo-font-display); font-weight: 700; font-size: 0.78rem; letter-spacing: 0.22em; color: var(--fo-orange); }
.fo-step__en { font-family: var(--fo-font-display); font-weight: 600; font-size: 1.15rem; }
.fo-step__ko { font-family: var(--fo-font-kr); color: var(--fo-mute); font-size: 0.9rem; }

.paper-fold-foot {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: clamp(1.5rem, 4vw, 2.5rem) 0;
  border-top: 1px solid var(--fo-line);
  font-size: 0.8rem;
  letter-spacing: 0.06em;
  color: var(--fo-mute);
  font-family: var(--fo-font-display);
}

/* ---- Reveal gating ---- */
.paper-fold-js [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 800ms var(--fo-ease), transform 800ms var(--fo-ease);
}
.paper-fold-js [data-reveal].is-visible { opacity: 1; transform: none; }
.paper-fold-js [data-reveal] { transition-delay: calc(var(--fo-d, 0) * 1ms); }
.paper-fold-js .paper-fold-glyph {
  opacity: 0;
  transform: translateY(0.35em);
  display: inline-block;
  transition: opacity 700ms var(--fo-ease), transform 700ms var(--fo-ease);
  transition-delay: calc(var(--fo-i) * 70ms + 150ms);
}
.paper-fold-js.is-mounted .paper-fold-glyph { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
  .paper-fold-js [data-reveal], .paper-fold-js .paper-fold-glyph {
    opacity: 1 !important; transform: none !important; transition: none !important;
  }
  .fo-crease { stroke-dashoffset: 0 !important; transition: none !important; }
}

.paper-fold-root :focus-visible {
  outline: 2px solid var(--fo-orange);
  outline-offset: 3px;
}

@media (max-width: 760px) {
  .paper-fold-steps { grid-template-columns: repeat(2, 1fr); }
}
